<div class="page-head"><div><h1>{{ $lead->first_name }} {{ $lead->last_name }}</h1><p class="muted">{{ $lead->company ?: 'Individual lead' }} · {{ $lead->mobile }}</p></div><div class="actions">@if($lead->mobile)<a class="btn primary" target="_blank" href="https://wa.me/{{ preg_replace('/\D+/','',$lead->whatsapp ?: $lead->mobile) }}">WhatsApp</a>@endif @if($lead->converted_contact_id)<a class="btn" href="{{ route('contacts.show',$lead->converted_contact_id) }}">Open Contact</a>@else<form method="POST" action="{{ route('leads.convert',$lead) }}">@csrf<button class="btn">Convert to Contact</button></form>@endif</div></div>
