@push('scripts')
<script>const templates=@json($templates->groupBy('situation'));const lead=@json(['mobile'=>$lead->whatsapp?:$lead->mobile]);const sel=document.getElementById('templateSelect'),prev=document.getElementById('preview'),btn=document.getElementById('waBtn');function fill(t){return t.replaceAll('{first_name}',@json($lead->first_name)).replaceAll('{last_name}',@json($lead->last_name??'')).replaceAll('{company}',@json($lead->company??'')).replaceAll('{requirement}',@json($lead->requirement??'')).replaceAll('{salesperson}',@json(request()->attributes->get('crmUser')->name)).replaceAll('{company_name}',@json(config('app.company_name')));}sel.addEventListener('change',()=>{const t=[...templates].flatMap(x=>x[1]).find(x=>String(x.id)===sel.value);prev.value=t?fill(t.body):'';btn.disabled=!t;btn.onclick=()=>window.open('https://wa.me/'+lead.mobile.replace(/\D/g,'')+'?text='+encodeURIComponent(prev.value),'_blank');});</script>
@endpush
